/**
 * 管理员相关API服务
 * 提供管理员账号管理功能
 */
import { ApiClient } from './client-api';
import { ApiResponse } from './definitions';
import {
    API_ADMIN_USER_LIST,
    API_ADMIN_USER_CREATE,
    API_ADMIN_USER_ACTIVATE,
    API_ADMIN_USER_DEACTIVATE,
    API_ADMIN_RESET_PASSWORD
} from './api-url';
import {
    AdminInfo,
    AdminListParams,
    AdminListResponseInfo,
    AdminActionResponse,
    AdminPasswordResetResponse,
    AdminCreateResponse,
    AdminCreateParams,
} from '../models/admin-models';

/**
 * 管理员API服务类
 * 集中管理所有管理员相关的API调用
 */

export class ApiAdmin {
    /**
     * 获取管理员列表
     * @returns 管理员列表响应
     */
    static async getAdminList(params:AdminListParams): Promise<ApiResponse<AdminInfo[]>> {
        const response = await ApiClient.post(
            API_ADMIN_USER_LIST,
            params
        );
        
        // 手动处理数组响应
        return {
            code: response.code,
            message: response.message,
            data: response.data as unknown as AdminInfo[]
        };
    }

    /**
     * 创建管理员
     * @param params 创建管理员参数
     * @returns 创建结果
     */
    static async createAdmin(params: AdminCreateParams): Promise<ApiResponse<AdminCreateResponse>> {
        return await ApiClient.post<AdminCreateResponse>(
            API_ADMIN_USER_CREATE,
            params,
            AdminCreateResponse
        );
    }

    /**
     * 重置管理员密码
     * @param adminId 管理员ID
     * @returns 重置结果，包含新密码
     */
    static async resetPassword(adminId: number): Promise<ApiResponse<AdminPasswordResetResponse>> {
        return await ApiClient.post<AdminPasswordResetResponse>(
            API_ADMIN_RESET_PASSWORD,
            { admin_id: adminId },
            AdminPasswordResetResponse
        );
    }

    /**
     * 禁用管理员账号
     * @param adminId 管理员ID
     * @returns 操作结果
     */
    static async deactivateAdmin(adminId: number): Promise<ApiResponse<AdminActionResponse>> {
        return await ApiClient.post<AdminActionResponse>(
            API_ADMIN_USER_DEACTIVATE,
            { admin_id: adminId },
            AdminActionResponse
        );
    }

    /**
     * 启用管理员账号
     * @param adminId 管理员ID
     * @returns 操作结果
     */
    static async activateAdmin(adminId: number): Promise<ApiResponse<AdminActionResponse>> {
        return await ApiClient.post<AdminActionResponse>(
            API_ADMIN_USER_ACTIVATE,
            { admin_id: adminId },
            AdminActionResponse
        );
    }
} 