/**
 * 管理员相关数据模型
 * 包含管理员账户、操作等所有相关模型
 */
import { BaseResponseData } from './base-models';

/**
 * 管理员基本信息
 */
export class AdminInfo extends BaseResponseData {
    /** 管理员ID */
    id: number;
    /** 管理员邮箱 */
    email: string;
    /** 管理员昵称 */
    nickname: string;
    /** 创建时间 */
    created_at: string;
    /** 是否激活 */
    is_active: boolean;
    /** 是否为超级管理员 */
    is_admin: boolean;
}

/**
 * 管理员列表响应
 */
export class AdminListResponseInfo extends BaseResponseData {
    /** 管理员列表 */
    items: AdminInfo[];
}

/**
 * 管理员操作响应
 */
export class AdminActionResponse extends BaseResponseData {
    /** 操作是否成功 */
    success: boolean;
    /** 操作消息 */
    message: string;
    /** 操作结果数据 */
    data: object | null = null;
}

/**
 * 管理员密码重置响应
 */
export class AdminPasswordResetResponse extends BaseResponseData {
    /** 管理员邮箱 */
    email: string;
    /** 管理员昵称 */
    nickname: string;
    /** 重置后的密码 */
    password: string;
}

/**
 * 管理员创建响应
 */
export class AdminCreateResponse extends BaseResponseData {
    /** 管理员邮箱 */
    email: string;
    /** 管理员昵称 */
    nickname: string;
    /** 生成的密码 */
    password: string;
}

/**
 * 创建管理员参数
 */
export interface AdminCreateParams {
    /** 管理员昵称 */
    nickname: string;
    /** 管理员邮箱 */
    email: string;
    /** 管理员密码（不提供时系统自动生成） */
    password?: string;
    /** 是否为超级管理员 */
    is_admin?: boolean;
}
export interface AdminListParams {
    page_size: number;
    cursor?: number;
}