<template>
  <mobile-bottom-sheet
    ref="bottomSheetRef"
    @onStateChange="handleStateChange"
    @onOpened="handleOpened"
    @onClosed="handleClosed"
    :showDragIndicator="false"
    :maskClosable="true"
  >
    <div 
      ref="editProfileSheetRef" 
      class="edit-profile-sheet" 
      @scroll="handleScroll"
      @touchstart="handleTouchStart"
      @touchmove="handleTouchMove"
      @touchend="handleTouchEnd"
    >
      <!-- 头部导航 -->
      <div 
        class="sheet-header"
        @touchstart="handleHeaderTouchStart"
        @touchmove="handleHeaderTouchMove"
        @touchend="handleHeaderTouchEnd"
      >
        <mobile-l-img src="/static/images/arrow-left.png" w="20px" h="20px" class="back-icon" @click="handleClose" />
        <div class="page-title">{{ $t('editProfile') }}</div>
        <div class="save-button" style="display: none;">{{ $t('save') }}</div>
      </div>

      <!-- 用户头像区域 -->
      <div class="user-profile-section">
                <div class="avatar-container">
          <div class="avatar-background">
            <div class="avatar-circle">
              <mobile-l-img 
                :src="userInfo?.avatar || '/static/avatar_def.png'" 
                w="80px" 
                h="80px" 
                :preview-list="[userInfo?.avatar || '/static/avatar_def.png']"
                radius="50%"
              />
            </div>
          </div>
          <!-- 编辑按钮 -->
          <div class="edit-profile-btn" @click="handleAvatarEditClick">
            <div class="edit-circle">
              <mobile-l-img src="/static/icon_edit.png" w="14px" h="14px" class="edit-icon" />
            </div>
          </div>
        </div>
      </div>
      
      <!-- 用户信息表单 -->
      <div class="user-form-section">
        <!-- 姓名字段 -->
        <div class="form-field">
          <div class="field-label">
            <div>{{ $t('fullName') }}</div>
          </div>
          <input 
            v-model="fullName" 
            class="field-input" 
            :placeholder="$t('fullName')"
            disabled
          />
        </div>

        <!-- 邮箱字段 -->
        <div class="form-field">
          <div class="field-label">
            <div>{{ $t('email') }}</div>
          </div>
          <input 
            v-model="email" 
            class="field-input" 
            :placeholder="$t('email')"
            disabled
          />
        </div>

        <!-- 登录方式字段 -->
        <div class="form-field">
          <div class="field-label">
            <div>{{ $t('loginMethod') }}</div>
          </div>
          <div class="login-method-display">
                         <mobile-l-img src="/static/images/email_icon.png" w="14px" h="14px" class="method-icon" />
            <div class="method-text">
              <div>{{ loginMethod }}</div>
            </div>
          </div>
        </div>

        <!-- 账户创建时间字段 -->
        <div class="form-field">
          <div class="field-label">
            <div>{{ $t('accountCreated') }}</div>
          </div>
          <div class="field-text">
            <div>{{ accountCreated }}</div>
          </div>
        </div>
      </div>
    </div>
  </mobile-bottom-sheet>
</template>

<script setup>
// 引入区域
import { ref, reactive, computed, watch, onMounted, nextTick } from 'vue';
import { useI18n } from 'vue-i18n';
import { useUserStore } from '@/store/modules/user';
import MobileLImg from '@/mobile/components/mobile-l-img.vue';import MobileBottomSheet, { SHEET_STATES } from '@/mobile/components/layout/mobile-bottom-sheet.vue';

// props 区域
const props = defineProps({
  visible: {
    type: Boolean,
    default: false
  }
});

// emits 区域  
const emit = defineEmits(['update:visible', 'onClose', 'onOpened', 'onClosed']);

// 变量区域
const { t } = useI18n();
const userStore = useUserStore();
const bottomSheetRef = ref(null);
const editProfileSheetRef = ref(null);

// 触摸事件相关变量
const touchStartY = ref(0);
const touchCurrentY = ref(0);
const isDragging = ref(false);
const isInEditProfileSheet = ref(false);
const isHeaderDragging = ref(false);
const TOUCH_THRESHOLD = 30; // 触发状态切换的滑动阈值（px）

// 响应式用户数据
const fullName = ref('');
const email = ref('');
const loginMethod = ref('');
const accountCreated = ref('');

// 计算属性区域
const visible = computed({
  get: () => props.visible,
  set: (value) => emit('update:visible', value)
});

const userInfo = computed(() => userStore.currentUser);

// 业务逻辑区域（需要在watch之前定义）
const updateFormData = (userInfo) => {
  // 从用户信息更新表单字段
  fullName.value = userInfo.nickname || '';
  email.value = userInfo.email || '';
  loginMethod.value = userInfo.loginMethod || 'Email';
  accountCreated.value = userInfo.displayCreatedAt_MDY_MonthAbbreviation || '';
};

// watch 区域
watch(() => props.visible, (newValue) => {
  if (newValue) {
    // 显示时直接展开到全屏（编辑资料是全屏弹窗）
    nextTick(() => {
      bottomSheetRef.value?.expandUp(SHEET_STATES.FULL);
    });
  } else {
    // 隐藏时收缩
    bottomSheetRef.value?.shrinkDown(SHEET_STATES.HIDDEN);
  }
}, { immediate: true });

// 监听用户信息变化，更新表单数据
watch(userInfo, (newUserInfo) => {
  if (newUserInfo) {
    updateFormData(newUserInfo);
  }
}, { immediate: true });

// 点击事件区域
const handleClose = () => {
  // 点击返回按钮关闭弹窗
  emit('onClose');
  visible.value = false;
};

const handleAvatarEditClick = (e) => {
  // 阻止事件冒泡，避免触发头像预览
  e.stopPropagation();
  // 预留头像编辑功能
  console.log('Avatar edit clicked - future avatar upload feature');
};

const handleScroll = () => {
  // 这里可以添加其他滚动相关的逻辑
};

// 触摸事件处理
const handleTouchStart = (e) => {
  touchStartY.value = e.touches[0].clientY;
  touchCurrentY.value = e.touches[0].clientY;
  isDragging.value = false;
  
  // 判断触摸位置是否在edit-profile-sheet内
  if (editProfileSheetRef.value) {
    const rect = editProfileSheetRef.value.getBoundingClientRect();
    const touchX = e.touches[0].clientX;
    const touchY = e.touches[0].clientY;
    
    isInEditProfileSheet.value = (
      touchX >= rect.left &&
      touchX <= rect.right &&
      touchY >= rect.top &&
      touchY <= rect.bottom
    );
  } else {
    isInEditProfileSheet.value = false;
  }
};

const handleTouchMove = (e) => {
  touchCurrentY.value = e.touches[0].clientY;
  const deltaY = touchCurrentY.value - touchStartY.value;
  
  // 如果移动距离超过阈值，认为是拖拽
  if (Math.abs(deltaY) > 5 && !isDragging.value) {
    isDragging.value = true;
  }
};

const handleTouchEnd = (e) => {
  if (!isDragging.value || !bottomSheetRef.value) {
    resetTouchState();
    return;
  }
  
  const deltaY = touchCurrentY.value - touchStartY.value;
  const currentState = bottomSheetRef.value.currentState;
  
  // 判断滑动逻辑
  if (isInEditProfileSheet.value && !isHeaderDragging.value) {
    // 在edit-profile-sheet内滑动，检查滚动位置
    if (!editProfileSheetRef.value) {
      resetTouchState();
      return;
    }
    
    const scrollTop = editProfileSheetRef.value.scrollTop;
    const scrollHeight = editProfileSheetRef.value.scrollHeight;
    const clientHeight = editProfileSheetRef.value.clientHeight;
    const isAtTop = scrollTop <= 5;
    const isAtBottom = scrollTop + clientHeight >= scrollHeight - 5;
    
    // 在顶部向下拖拽超过阈值
    if (isAtTop && deltaY > TOUCH_THRESHOLD) {
      handleStateSwitch(deltaY, currentState);
    }
    // 在顶部向上拖拽超过阈值
    else if (isAtTop && deltaY < -TOUCH_THRESHOLD) {
      handleStateSwitch(deltaY, currentState);
    }
    // 在底部向下拖拽超过阈值
    else if (isAtBottom && deltaY > TOUCH_THRESHOLD) {
      handleStateSwitch(deltaY, currentState);
    }
    // 在底部向上拖拽超过阈值
    else if (isAtBottom && deltaY < -TOUCH_THRESHOLD) {
      handleStateSwitch(deltaY, currentState);
    }
  } else {
    // 不在edit-profile-sheet内滑动或者是header拖拽，直接处理
    if (Math.abs(deltaY) > TOUCH_THRESHOLD) {
      handleStateSwitch(deltaY, currentState);
    }
  }
  
  resetTouchState();
};

// Header特殊拖拽处理
const handleHeaderTouchStart = (e) => {
  isHeaderDragging.value = true;
  handleTouchStart(e);
};

const handleHeaderTouchMove = (e) => {
  if (isHeaderDragging.value) {
    handleTouchMove(e);
  }
};

const handleHeaderTouchEnd = (e) => {
  if (isHeaderDragging.value) {
    handleTouchEnd(e);
  }
  isHeaderDragging.value = false;
};

// 状态切换处理
const handleStateSwitch = (deltaY, currentState) => {
  if (deltaY > 0) {
    // 向下滑动
    if (currentState === SHEET_STATES.FULL) {
      // 90vh -> 50vh
      bottomSheetRef.value.shrinkDown(SHEET_STATES.HALF);
    } else if (currentState === SHEET_STATES.HALF) {
      // 50vh -> 隐藏
      visible.value = false;
    } else {
      // 已经是隐藏状态，不处理
    }
  } else {
    // 向上滑动
    if (currentState === SHEET_STATES.HALF) {
      // 50vh -> 90vh
      bottomSheetRef.value.expandUp(SHEET_STATES.FULL);
    } else {
      // 已经是全屏状态，不处理
    }
  }
};

// 重置触摸状态
const resetTouchState = () => {
  touchStartY.value = 0;
  touchCurrentY.value = 0;
  isDragging.value = false;
  isInEditProfileSheet.value = false;
  isHeaderDragging.value = false;
};

// 自定义事件区域
const handleStateChange = (newState) => {
  // 当弹窗状态变为隐藏时，更新父组件的 visible 状态
  if (newState === SHEET_STATES.HIDDEN) {
    emit('update:visible', false);
  }
};

const handleOpened = () => {
  // 弹窗打开时的回调
  emit('onOpened');
  resetTouchState();
};

const handleClosed = () => {
  // 弹窗关闭时的回调
  emit('onClosed');
  visible.value = false;
  resetTouchState();
};

// 初始化方法区域
const initData = () => {
  // 初始化时从pinia获取用户数据
  if (userInfo.value) {
    updateFormData(userInfo.value);
  }
};

// 周期函数区域
onMounted(() => {
  initData();
});

// 导出区域
defineExpose({
  // 暴露给父组件的方法
});
</script>

