<template>
  <mobile-bottom-sheet
    ref="bottomSheetRef"
    @onStateChange="handleStateChange"
    @onOpened="handleOpened"
    @onClosed="handleClosed"
    :showDragIndicator="false"
    :maskClosable="true"
  >
    <div 
      ref="settingsSheetRef" 
      class="mobile-settings-sheet" 
      @scroll="handleScroll"
      @touchstart="handleTouchStart"
      @touchmove="handleTouchMove"
      @touchend="handleTouchEnd"
    >
      <!-- 头部标题 -->
      <div class="sheet-header">
        <h1 class="page-title">{{ $t('settings') }}</h1>
      </div>
      <div class="close-btn" @click="handleClose">
        <mobile-l-img src="/static/images/mobaile-close-icon.png" w="32px" h="32px" />
      </div>

      <!-- 用户头像区域 -->
      <div class="user-me-section">
        <div class="avatar-container">
          <div class="avatar-background">
            <div class="avatar-circle">
              <mobile-l-img 
                :src="userInfo.avatar || '/static/avatar_def.png'" 
                w="80px" 
                h="80px" 
              />
               <!-- 编辑按钮 -->
        <div class="edit-me-btn" @click="handleEditMe">
          <div class="edit-circle">
            <mobile-l-img src="/static/icon_edit.png" w="14px" h="14px" />
          </div>
        </div>
            </div>
          </div>
        </div>
    
      </div>

      <!-- 用户信息 -->
      <div class="user-info-section">
        <div class="user-name">{{ userInfo.name || $t('unknown') }}</div>
        <div class="user-email">{{ userInfo.email || '' }}</div>
      </div>

      <!-- 设置选项列表 -->
      <div class="settings-options">
        <!-- 生成的图片 -->
        <div class="setting-item" @click="navigateTo('generated-images')">
          <div class="setting-icon">
            <mobile-l-img src="/static/images/generated-images.png" w="16px" h="16px" />
          </div>
          <span class="setting-text">{{ $t('generatedImages') }}</span>
        </div>

        <!-- 生成的视频 -->
        <div class="setting-item" @click="navigateTo('generated-videos')">
          <div class="setting-icon">
            <mobile-l-img src="/static/images/generated-videos.png" w="16px" h="16px" />
          </div>
          <span class="setting-text">{{ $t('generatedVideos') }}</span>
        </div>

        <!-- 我的收藏 -->
        <div class="setting-item" @click="navigateTo('my-favorites')">
          <div class="setting-icon">
            <mobile-l-img src="/static/images/my-favorites.png" w="16px" h="16px" />
          </div>
          <span class="setting-text">{{ $t('myFavorites') }}</span>
        </div>

        <!-- 管理员列表 -->
        <div v-if="isAdmin" class="setting-item" @click="showAdminListSheet">
          <div class="setting-icon">
            <mobile-l-img src="/static/images/admin_list_icon.png" w="16px" h="16px" />
          </div>
          <span class="setting-text">{{ $t('adminList') }}</span>
        </div>

        <!-- 退出登录 -->
        <div class="setting-item" @click="handleSignOut">
          <div class="setting-icon">
            <mobile-l-img src="/static/images/logout_icon.png" w="16px" h="16px" />
          </div>
          <span class="setting-text">{{ $t('signOut') }}</span>
        </div>
      </div>
    </div>

    <!-- 管理员列表弹层 -->
    <mobile-admin-list-sheet
      v-model:visible="adminListSheetVisible"
      @onClose="handleAdminListClose"
    />

    <!-- 编辑资料弹层 -->
    <mobile-edit-me-sheet
      v-model:visible="editMeSheetVisible"
      @onClose="handleEditMeClose"
    />
  </mobile-bottom-sheet>
</template>

<script setup>
import { ref, computed, onMounted, nextTick, watch } from 'vue';
import { useRouter } from 'vue-router';
import { useI18n } from 'vue-i18n';
import { useUserStore } from '@/store/modules/user';
import MobileLImg from '@/mobile/components/mobile-l-img.vue';import MobileBottomSheet, { SHEET_STATES } from '@/mobile/components/layout/mobile-bottom-sheet.vue';
import MobileAdminListSheet from './mobile-admin-list-sheet.vue';
import MobileEditMeSheet from './mobile-edit-me-sheet.vue';
import { showUIFeedback } from '@/utils/mobile-ui-feedback';
import { ApiUser } from '@/api/api-user';
import { routerToLogin } from '@/router/navigation';

// props区域
const props = defineProps({
  visible: { type: Boolean, default: false },
  showDemo: { type: Boolean, default: false } // 是否显示演示区域
});

// emits区域
const emit = defineEmits(['update:visible', 'onOpened', 'onClosed', 'onClose']);

const { t } = useI18n();
const router = useRouter();
const userStore = useUserStore();

// 变量区域
const bottomSheetRef = ref(null);
const adminListSheetVisible = ref(false);
const editMeSheetVisible = ref(false);
const demoSheetVisible = ref(false);
const settingsSheetRef = ref(null);
const userInfo = ref({
  name: 'Groot',
  email: 'momory2620@gmail.com',
  avatar: '/static/avatar_def.png'
});

// 触摸事件相关变量
const touchStartY = ref(0);
const touchCurrentY = ref(0);
const isDragging = ref(false);
const isInSettingsSheet = ref(false);
const TOUCH_THRESHOLD = 30; // 触发状态切换的滑动阈值（px）

// 计算属性区域
const visible = computed({
  get: () => props.visible,
  set: (value) => emit('update:visible', value)
});

const isAdmin = computed(() => userStore.isAdmin);

// watch 区域
watch(() => props.visible, (newValue) => {
  if (newValue) {
    // 显示时展开到半屏
    nextTick(() => {
      bottomSheetRef.value?.expandUp(SHEET_STATES.HALF);
    });
  } else {
    // 隐藏时收缩
    bottomSheetRef.value?.shrinkDown(SHEET_STATES.HIDDEN);
  }
}, { immediate: true });

// 点击事件区域
const handleEditMe = () => {
  editMeSheetVisible.value = true;
};

const showAdminListSheet = () => {
  adminListSheetVisible.value = true;
};

const showDemoSheet = () => {
  demoSheetVisible.value = true;
};

const showLongContentDemo = () => {
  demoSheetVisible.value = true;
};

const handleScroll = () => {
  // 这里可以添加其他滚动相关的逻辑
};

// 触摸事件处理
const handleTouchStart = (e) => {
  touchStartY.value = e.touches[0].clientY;
  touchCurrentY.value = e.touches[0].clientY;
  isDragging.value = false;
  
  // 判断触摸位置是否在settings-sheet内
  if (settingsSheetRef.value) {
    const rect = settingsSheetRef.value.getBoundingClientRect();
    const touchX = e.touches[0].clientX;
    const touchY = e.touches[0].clientY;
    
    isInSettingsSheet.value = (
      touchX >= rect.left &&
      touchX <= rect.right &&
      touchY >= rect.top &&
      touchY <= rect.bottom
    );
  } else {
    isInSettingsSheet.value = false;
  }
};

const handleTouchMove = (e) => {
  touchCurrentY.value = e.touches[0].clientY;
  const deltaY = touchCurrentY.value - touchStartY.value;
  
  // 如果移动距离超过阈值，认为是拖拽
  if (Math.abs(deltaY) > 5 && !isDragging.value) {
    isDragging.value = true;
  }
};

const handleTouchEnd = (e) => {
  
  if (!isDragging.value || !bottomSheetRef.value) {
    resetTouchState();
    return;
  }
  
  const deltaY = touchCurrentY.value - touchStartY.value;
  const currentState = bottomSheetRef.value.currentState;
  
  // 判断滑动逻辑
  if (isInSettingsSheet.value) {
    // 在settings-sheet内滑动，检查滚动位置
    if (!settingsSheetRef.value) {
      resetTouchState();
      return;
    }
    
    const scrollTop = settingsSheetRef.value.scrollTop;
    const scrollHeight = settingsSheetRef.value.scrollHeight;
    const clientHeight = settingsSheetRef.value.clientHeight;
    const isAtTop = scrollTop <= 5;
    const isAtBottom = scrollTop + clientHeight >= scrollHeight - 5;
    
    
    // 在顶部向下拖拽超过阈值
    if (isAtTop && deltaY > TOUCH_THRESHOLD) {
      handleStateSwitch(deltaY, currentState);
    }
    // 在顶部向上拖拽超过阈值
    else if (isAtTop && deltaY < -TOUCH_THRESHOLD) {
      handleStateSwitch(deltaY, currentState);
    }
    // 在底部向下拖拽超过阈值
    else if (isAtBottom && deltaY > TOUCH_THRESHOLD) {
      handleStateSwitch(deltaY, currentState);
    }
    // 在底部向上拖拽超过阈值
    else if (isAtBottom && deltaY < -TOUCH_THRESHOLD) {
      handleStateSwitch(deltaY, currentState);
    }
    else {
    }
  } else {
    // 不在settings-sheet内滑动，直接处理
    if (Math.abs(deltaY) > TOUCH_THRESHOLD) {
      handleStateSwitch(deltaY, currentState);
    } else {
    }
  }
  
  resetTouchState();
};

// 状态切换处理
const handleStateSwitch = (deltaY, currentState) => {
  
  if (deltaY > 0) {
    // 向下滑动
    if (currentState === SHEET_STATES.FULL) {
      // 90vh -> 50vh
      bottomSheetRef.value.shrinkDown(SHEET_STATES.HALF);
    } else if (currentState === SHEET_STATES.HALF) {
      // 50vh -> 隐藏
      visible.value = false;
    } else {
    }
  } else {
    // 向上滑动
    if (currentState === SHEET_STATES.HALF) {
      // 50vh -> 90vh
      bottomSheetRef.value.expandUp(SHEET_STATES.FULL);
    } else {
    }
  }
};

// 重置触摸状态
const resetTouchState = () => {
  touchStartY.value = 0;
  touchCurrentY.value = 0;
  isDragging.value = false;
  isInSettingsSheet.value = false;
};

// 自定义事件区域
const handleClose = () => {
  emit('onClose');
  visible.value = false;
};

const handleStateChange = (newState) => {
  // 当弹窗状态变为隐藏时，更新父组件的 visible 状态
  if (newState === SHEET_STATES.HIDDEN) {
    emit('update:visible', false);
  }
};

const handleOpened = () => {
  emit('onOpened');
  resetTouchState();
};

const handleClosed = () => {
  emit('onClosed');
  resetTouchState();
};

const handleAdminListClose = () => {
  console.log('Admin list sheet closed');
};

const handleEditMeClose = () => {
  editMeSheetVisible.value = false;
};

// 业务逻辑区域
const navigateTo = (routeName) => {
  // 关闭设置弹窗
  visible.value = false;
  // 等待弹窗关闭动画完成后跳转
  setTimeout(() => {
    router.push({ name: routeName });
  }, 300);
};

const handleSignOut = async () => {
  try {
    await showUIFeedback.confirm(
      t('confirmSignOut'),
      t('signOut')
    );
    
    // 执行登出
    await ApiUser.logout();
    userStore.clearUserInfo();
    
    showUIFeedback.success(t('signOutSuccess'));
    
    // 关闭弹窗
    visible.value = false;
    
    // 跳转到登录页
    setTimeout(() => {
      routerToLogin();
    }, 300);
  } catch (error) {
    if (error !== 'cancel') {
      showUIFeedback.error(t('signOutFailed'));
      console.error('Sign out failed:', error);
    }
  }
};

// 初始化方法区域
const initUserInfo = () => {
  const currentUser = userStore.userInfo;
  if (currentUser) {
    userInfo.value = {
      name: currentUser.name || currentUser.nickname || 'Groot',
      email: currentUser.email || 'momory2620@gmail.com',
      avatar: currentUser.avatar || '/static/avatar_def.png'
    };
  }
};

// 周期函数区域
onMounted(() => {
  initUserInfo();
});
</script>

