<template>
  <teleport to="body">
    <div 
      v-show="isVisible" 
      class="mobile-bottom-sheet" 
      :style="{ zIndex: zIndex }"
    >
      <!-- 遮罩层 -->
      <div
        class="bottom-sheet__mask"
        :style="maskStyle"
        @click="handleMaskClick"
      ></div>

      <!-- 内容层 -->
      <div
        ref="contentRef"
        class="bottom-sheet__content"
        :class="`bottom-sheet__content--${currentState}`"
        :style="contentStyle"
      >
        <!-- 拖拽指示器 -->
        <div 
          v-if="showDragIndicator"
          ref="dragIndicatorRef"
          class="bottom-sheet__drag-indicator"
        ></div>
        
        <!-- 内容插槽 -->
        <div class="bottom-sheet__body">
          <slot></slot>
        </div>
      </div>
    </div>
  </teleport>
</template>

<script>
// 状态枚举
export const SHEET_STATES = {
  HIDDEN: 'hidden',
  HALF: 'half',     // 50vh
  FULL: 'full'      // 90vh
};
</script>

<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue';

// props区域
const props = defineProps({
  maskClosable: {
    type: Boolean,
    default: true
  },
  zIndex: {
    type: Number,
    default: 1000
  },
  showDragIndicator: {
    type: Boolean,
    default: true
  }
});

// emits区域
const emit = defineEmits(['onStateChange', 'onOpened', 'onClosed']);

// 变量区域
const contentRef = ref(null);
const dragIndicatorRef = ref(null);
const currentState = ref(SHEET_STATES.HIDDEN); // 当前状态，默认隐藏
const isAnimating = ref(false); // 是否正在动画中
const originalBodyOverflow = ref('');
// 拖拽相关变量
const isDragging = ref(false); // 是否正在拖拽
const dragStartY = ref(0); // 拖拽开始的Y坐标
const dragCurrentY = ref(0); // 当前拖拽的Y坐标
const indicatorThreshold = 15; // 指示器拖拽阈值，超过此值才触发状态切换
const scrollThreshold = 40; // 滚动阈值，用于防止滚动冲突

// 计算属性区域
const isVisible = computed(() => {
  return currentState.value !== SHEET_STATES.HIDDEN;
});

const contentStyle = computed(() => {
  const style = {
    transition: isAnimating.value ? 'transform 300ms ease-out, height 300ms ease-out' : 'none'
  };
  
  // 根据状态设置位置和高度
  switch (currentState.value) {
    case SHEET_STATES.HIDDEN:
      style.transform = 'translateY(100%)';
      style.height = '50vh';
      break;
    case SHEET_STATES.HALF:
      style.transform = 'translateY(0px)';
      style.height = '50vh';
      break;
    case SHEET_STATES.FULL:
      style.transform = 'translateY(0px)';
      style.height = '90vh';
      break;
  }
  
  return style;
});

const maskStyle = computed(() => {
  return {
    opacity: currentState.value === SHEET_STATES.HIDDEN ? 0 : 1,
    transition: isAnimating.value ? 'opacity 300ms ease-out' : 'none'
  };
});

// 点击事件区域
const handleMaskClick = () => {
  if (props.maskClosable) {
    // 点击遮罩层直接关闭到隐藏状态
    changeState(SHEET_STATES.HIDDEN);
  }
};

// 自定义事件区域
const onTouchStartIndicator = (event) => {
  // 安全地阻止默认行为
  try {
    if (event.cancelable) {
      event.preventDefault();
    }
  } catch (error) {
    // 静默处理防止默认行为失败的情况
    console.debug('触摸事件防止默认行为失败:', error);
  }
  
  isDragging.value = true;
  dragStartY.value = event.touches[0].clientY;
  dragCurrentY.value = dragStartY.value;
};

const onTouchMoveIndicator = (event) => {
  if (!isDragging.value) return;
  
  dragCurrentY.value = event.touches[0].clientY;
  const currentDragDistance = Math.abs(dragStartY.value - dragCurrentY.value);
  
  // 当拖拽距离超过滚动阈值时，阻止默认滚动行为
  if (currentDragDistance > scrollThreshold) {
    try {
      if (event.cancelable) {
        event.preventDefault();
      }
    } catch (error) {
      // 静默处理防止默认行为失败的情况
      console.debug('触摸移动事件防止默认行为失败:', error);
    }
  }
};

const onTouchEndIndicator = (event) => {
  if (!isDragging.value) return;
  
  // 安全地阻止默认行为
  try {
    if (event.cancelable) {
      event.preventDefault();
    }
  } catch (error) {
    // 静默处理防止默认行为失败的情况
    console.debug('触摸结束事件防止默认行为失败:', error);
  }
  
  const dragDistance = dragStartY.value - dragCurrentY.value; // 向上为正值，向下为负值
  const absDragDistance = Math.abs(dragDistance);
  
  // 如果拖拽距离超过指示器阈值，触发状态切换
  if (absDragDistance > indicatorThreshold) {
    if (dragDistance > 0) {
      // 向上拖拽，展开
      expandUp();
    } else {
      // 向下拖拽，收缩
      shrinkDown();
    }
  }
  
  // 重置拖拽状态
  isDragging.value = false;
  dragStartY.value = 0;
  dragCurrentY.value = 0;
};

// 业务逻辑区域
const changeState = (newState) => {
  if (newState !== currentState.value && !isAnimating.value) {
    const oldState = currentState.value;
    currentState.value = newState;
    isAnimating.value = true;
    
    // 控制body滚动
    if (newState !== SHEET_STATES.HIDDEN && oldState === SHEET_STATES.HIDDEN) {
      preventBodyScroll();
      emit('onOpened');
    } else if (newState === SHEET_STATES.HIDDEN && oldState !== SHEET_STATES.HIDDEN) {
      // 延迟恢复body滚动，等待动画完成
      setTimeout(() => {
        restoreBodyScroll();
        emit('onClosed');
      }, 300);
    }
    
    emit('onStateChange', newState);
    
    // 动画完成后重置动画状态
    setTimeout(() => {
      isAnimating.value = false;
    }, 300);
  }
};

const preventBodyScroll = () => {
  originalBodyOverflow.value = document.body.style.overflow;
  document.body.style.overflow = 'hidden';
};

const restoreBodyScroll = () => {
  document.body.style.overflow = originalBodyOverflow.value;
};

// 暴露给父组件的方法
const expandUp = (targetState = null) => {
  if (targetState) {
    // 如果传入了目标状态，直接跳转到指定状态
    if (Object.values(SHEET_STATES).includes(targetState)) {
      changeState(targetState);
    }
    return;
  }
  
  // 默认逐级向上切换
  switch (currentState.value) {
    case SHEET_STATES.HIDDEN:
      changeState(SHEET_STATES.HALF);
      break;
    case SHEET_STATES.HALF:
      changeState(SHEET_STATES.FULL);
      break;
    case SHEET_STATES.FULL:
      // 已经是最大状态，不处理
      break;
  }
};

const shrinkDown = (targetState = null) => {
  if (targetState) {
    // 如果传入了目标状态，直接跳转到指定状态
    if (Object.values(SHEET_STATES).includes(targetState)) {
      changeState(targetState);
    }
    return;
  }
  
  // 默认逐级向下切换
  switch (currentState.value) {
    case SHEET_STATES.FULL:
      changeState(SHEET_STATES.HALF);
      break;
    case SHEET_STATES.HALF:
      changeState(SHEET_STATES.HIDDEN);
      break;
    case SHEET_STATES.HIDDEN:
      // 已经是最小状态，不处理
      break;
  }
};

// 初始化方法区域
const initDragEvents = () => {
  if (dragIndicatorRef.value) {
    // 使用 addEventListener 并设置 passive: false 来尽可能确保事件可取消
    // 但仍需要在事件处理器中检查 event.cancelable
    dragIndicatorRef.value.addEventListener('touchstart', onTouchStartIndicator, { 
      passive: false,
      capture: true // 使用捕获阶段来更早处理事件
    });
    dragIndicatorRef.value.addEventListener('touchmove', onTouchMoveIndicator, { 
      passive: false,
      capture: true 
    });
    dragIndicatorRef.value.addEventListener('touchend', onTouchEndIndicator, { 
      passive: false,
      capture: true 
    });
  }
};

const removeDragEvents = () => {
  if (dragIndicatorRef.value) {
    dragIndicatorRef.value.removeEventListener('touchstart', onTouchStartIndicator);
    dragIndicatorRef.value.removeEventListener('touchmove', onTouchMoveIndicator);
    dragIndicatorRef.value.removeEventListener('touchend', onTouchEndIndicator);
  }
};

// 周期函数区域
onMounted(() => {
  if (props.showDragIndicator) {
    initDragEvents();
  }
});

onUnmounted(() => {
  removeDragEvents();
  restoreBodyScroll();
});

// 导出区域
defineExpose({
  expandUp,
  shrinkDown,
  currentState,
  SHEET_STATES
});
</script>

<style scoped lang="scss">
.mobile-bottom-sheet {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}

.bottom-sheet__mask {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.5);
}

.bottom-sheet__content {
  position: relative;
  width: 100%;
 
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: 0 -4px 20px rgba(0, 0, 0, 0.1);
  transform: translateY(100%);
}

.bottom-sheet__drag-indicator {
  width: 36px;
  height: 4px;
  background: var(--text-label);
  border-radius: 2px;
  margin: 12px auto 8px;
  flex-shrink: 0;
  opacity: 0.6;
  cursor: grab;
  touch-action: none; // 防止默认的触摸行为
  user-select: none; // 防止选中文本
  transition: opacity 0.2s ease;
  
  &:active {
    cursor: grabbing;
    opacity: 0.8;
  }
  
  &:hover {
    opacity: 0.8;
  }
}

.bottom-sheet__body {
  flex: 1;
  overflow: auto;
  
  // 自定义滚动条
  &::-webkit-scrollbar {
    width: 3px;
  }
  
  &::-webkit-scrollbar-track {
    background: transparent;
  }
  
  &::-webkit-scrollbar-thumb {
    background: var(--text-label);
    border-radius: 3px;
    opacity: 0.3;
  }
  
  &::-webkit-scrollbar-thumb:hover {
    opacity: 0.6;
  }
}

</style> 