<template>
  <mobile-bottom-sheet
    ref="bottomSheetRef"
    @onStateChange="handleStateChange"
    @onOpened="handleOpened"
    @onClosed="handleClosed"
    :showDragIndicator="false"
    :maskClosable="true"
  >
    <div 
      ref="createAdminSheetRef" 
      class="create-admin-sheet"
      @scroll="handleScroll"
      @touchstart="handleTouchStart"
      @touchmove="handleTouchMove"
      @touchend="handleTouchEnd"
    >
      <!-- 头部导航区域 - 对应设计图顶部 -->
      <div 
        class="sheet-header"
        @touchstart="handleHeaderTouchStart"
        @touchmove="handleHeaderTouchMove"
        @touchend="handleHeaderTouchEnd"
      >
        <mobile-l-img 
          src="/static/images/arrow-left.png" 
          w="20px" 
          h="20px" 
          class="back-icon" 
          @click="handleClose" 
        />
        <div class="page-title">{{ $t('createAdminAccount') }}</div>
        <div class="placeholder"></div>
      </div>

      <!-- 表单区域 - 对应设计图表单部分 -->
      <div class="form-section">
        <!-- 昵称字段 -->
        <div class="form-field">
          <div class="field-label">
            <span class="label-text">{{ $t('nickname') }}</span>
          </div>
          <div class="input-container">
            <van-field
              v-model="createForm.nickname"
              :placeholder="$t('enterNickname')"
              class="field-input"
              clearable
              maxlength="50"
            />
          </div>
        </div>

        <!-- 邮箱字段 -->
        <div class="form-field">
          <div class="field-label">
            <span class="label-text">{{ $t('email') }}</span>
          </div>
          <div class="input-container">
            <van-field
              v-model="createForm.email"
              :placeholder="$t('enterEmail')"
              class="field-input"
              clearable
              type="email"
              autocomplete="new-email"
            />
          </div>
        </div>

        <!-- 密码字段 -->
        <div class="form-field">
          <div class="field-label">
            <span class="label-text">{{ $t('password') }}</span>
          </div>
          <div class="input-container">
            <van-field
              v-model="createForm.password"
              :placeholder="$t('enterPassword')"
              class="field-input"
              clearable
              :type="passwordFieldType"
              autocomplete="new-password"
              maxlength="20"
            >
              <!-- <template #right-icon>
                <div class="password-icon" @click="togglePasswordVisibility">
                  <mobile-l-img 
                    :src="showPassword ? '/static/images/password-show.png' : '/static/images/password-hide.png'" 
                    w="16px" 
                    h="16px" 
                  />
                </div>
              </template> -->
            </van-field>
          </div>
        </div>

        <!-- 超级管理员权限复选框 - 对应设计图复选框区域 -->
        <div class="checkbox-field">
          <div class="checkbox" @click="createForm.is_admin = !createForm.is_admin">
            <div class="checkbox-inner" :class="{ 'checked': createForm.is_admin }">
              <mobile-l-img v-if="createForm.is_admin" :src="'/static/images/password-show.png'" w="12px" h="12px" />
              <mobile-l-img v-else :src="'/static/images/password-hide.png'" w="14px" h="14px" />
            </div>
          </div>
          <div class="checkbox-label" @click="createForm.is_admin = !createForm.is_admin">
            {{ $t('canCreateAccounts') }}
          </div>
        </div>
      </div>

      <!-- 操作按钮区域 - 对应设计图底部按钮 -->
      <div class="action-buttons">
        <div class="cancel-button" @click="handleClose">
          {{ $t('cancel') }}
        </div>
        <div 
          class="create-button" 
          :class="{ 'disabled': submitting || !isFormValid }"
          @click="handleCreateAdmin"
        >
          {{ submitting ? $t('creating') : $t('createAccount') }}
        </div>
      </div>
    </div>
  </mobile-bottom-sheet>
</template>

<script setup>
// 引入区域
import { ref, reactive, computed, watch, onMounted, nextTick } from 'vue';
import { useI18n } from 'vue-i18n';
import MobileLImg from '@/mobile/components/mobile-l-img.vue';
import MobileBottomSheet, { SHEET_STATES } from '@/mobile/components/layout/mobile-bottom-sheet.vue';
import { ApiAdmin } from '@/api/api-admin';
import { copy } from '@/utils/util';
import { showUIFeedback } from '@/utils/mobile-ui-feedback';

// props 区域
const props = defineProps({
  visible: {
    type: Boolean,
    default: false
  }
});

// emits 区域
const emit = defineEmits(['update:visible', 'onClose', 'onOpened', 'onClosed', 'onAdminCreated']);

// 变量区域
const { t } = useI18n();
const bottomSheetRef = ref(null);
const createAdminSheetRef = ref(null);

// 触摸事件相关变量
const touchStartY = ref(0);
const touchCurrentY = ref(0);
const isDragging = ref(false);
const isInCreateAdminSheet = ref(false);
const isHeaderDragging = ref(false);
const TOUCH_THRESHOLD = 30; // 触发状态切换的滑动阈值（px）

// 表单数据
const createForm = reactive({
  nickname: '',
  email: '',
  password: '',
  is_admin: false
});

// 业务逻辑变量
const submitting = ref(false);
const showPassword = ref(false);

// 计算属性区域
const visible = computed({
  get: () => props.visible,
  set: (value) => emit('update:visible', value)
});

const passwordFieldType = computed(() => {
  return showPassword.value ? 'text' : 'password';
});

const isFormValid = computed(() => {
  return createForm.nickname.trim() && 
         createForm.email.trim() && 
         createForm.password.trim() &&
         validateEmail(createForm.email) &&
         createForm.password.length >= 6;
});

// watch 区域
watch(() => props.visible, (newValue) => {
  if (newValue) {
    // 显示时直接展开到全屏
    nextTick(() => {
      bottomSheetRef.value?.expandUp(SHEET_STATES.FULL);
    });
  } else {
    // 隐藏时收缩
    bottomSheetRef.value?.shrinkDown(SHEET_STATES.HIDDEN);
  }
}, { immediate: true });

// 点击事件区域
const handleClose = () => {
  emit('onClose');
  visible.value = false;
};

// 自定义事件区域
const handleScroll = () => {
  // 滚动事件处理
};

// 触摸事件处理
const handleTouchStart = (e) => {
  touchStartY.value = e.touches[0].clientY;
  touchCurrentY.value = e.touches[0].clientY;
  isDragging.value = false;
  
  // 判断触摸位置是否在create-admin-sheet内
  if (createAdminSheetRef.value) {
    const rect = createAdminSheetRef.value.getBoundingClientRect();
    const touchX = e.touches[0].clientX;
    const touchY = e.touches[0].clientY;
    
    isInCreateAdminSheet.value = (
      touchX >= rect.left &&
      touchX <= rect.right &&
      touchY >= rect.top &&
      touchY <= rect.bottom
    );
  } else {
    isInCreateAdminSheet.value = false;
  }
};

const handleTouchMove = (e) => {
  touchCurrentY.value = e.touches[0].clientY;
  const deltaY = touchCurrentY.value - touchStartY.value;
  
  // 如果移动距离超过阈值，认为是拖拽
  if (Math.abs(deltaY) > 5 && !isDragging.value) {
    isDragging.value = true;
  }
};

const handleTouchEnd = (e) => {
  if (!isDragging.value || !bottomSheetRef.value) {
    resetTouchState();
    return;
  }
  
  const deltaY = touchCurrentY.value - touchStartY.value;
  const currentState = bottomSheetRef.value.currentState;
  
  // 判断滑动逻辑
  if (isInCreateAdminSheet.value && !isHeaderDragging.value) {
    // 在create-admin-sheet内滑动，检查滚动位置
    if (!createAdminSheetRef.value) {
      resetTouchState();
      return;
    }
    
    const scrollTop = createAdminSheetRef.value.scrollTop;
    const scrollHeight = createAdminSheetRef.value.scrollHeight;
    const clientHeight = createAdminSheetRef.value.clientHeight;
    const isAtTop = scrollTop <= 5;
    const isAtBottom = scrollTop + clientHeight >= scrollHeight - 5;
    
    // 在顶部向下拖拽超过阈值
    if (isAtTop && deltaY > TOUCH_THRESHOLD) {
      handleStateSwitch(deltaY, currentState);
    }
    // 在顶部向上拖拽超过阈值
    else if (isAtTop && deltaY < -TOUCH_THRESHOLD) {
      handleStateSwitch(deltaY, currentState);
    }
    // 在底部向下拖拽超过阈值
    else if (isAtBottom && deltaY > TOUCH_THRESHOLD) {
      handleStateSwitch(deltaY, currentState);
    }
    // 在底部向上拖拽超过阈值
    else if (isAtBottom && deltaY < -TOUCH_THRESHOLD) {
      handleStateSwitch(deltaY, currentState);
    }
  } else {
    // 不在create-admin-sheet内滑动或者是header拖拽，直接处理
    if (Math.abs(deltaY) > TOUCH_THRESHOLD) {
      handleStateSwitch(deltaY, currentState);
    }
  }
  
  resetTouchState();
};

// Header特殊拖拽处理
const handleHeaderTouchStart = (e) => {
  isHeaderDragging.value = true;
  handleTouchStart(e);
};

const handleHeaderTouchMove = (e) => {
  if (isHeaderDragging.value) {
    handleTouchMove(e);
  }
};

const handleHeaderTouchEnd = (e) => {
  if (isHeaderDragging.value) {
    handleTouchEnd(e);
  }
  isHeaderDragging.value = false;
};

// 状态切换处理
const handleStateSwitch = (deltaY, currentState) => {
  if (deltaY > 0) {
    // 向下滑动
    if (currentState === SHEET_STATES.FULL) {
      // 90vh -> 50vh
      bottomSheetRef.value.shrinkDown(SHEET_STATES.HALF);
    } else if (currentState === SHEET_STATES.HALF) {
      // 50vh -> 隐藏
      visible.value = false;
    } else {
      // 已经是隐藏状态，不处理
    }
  } else {
    // 向上滑动
    if (currentState === SHEET_STATES.HALF) {
      // 50vh -> 90vh
      bottomSheetRef.value.expandUp(SHEET_STATES.FULL);
    } else {
      // 已经是全屏状态，不处理
    }
  }
};

// 重置触摸状态
const resetTouchState = () => {
  touchStartY.value = 0;
  touchCurrentY.value = 0;
  isDragging.value = false;
  isInCreateAdminSheet.value = false;
  isHeaderDragging.value = false;
};

const handleStateChange = (newState) => {
  // 当弹窗状态变为隐藏时，更新父组件的 visible 状态
  if (newState === SHEET_STATES.HIDDEN) {
    emit('update:visible', false);
  }
};

const handleOpened = () => {
  // 弹窗打开时的回调
  emit('onOpened');
  resetTouchState();
};

const handleClosed = () => {
  // 弹窗关闭时的回调
  emit('onClosed');
  visible.value = false;
  resetTouchState();
};

// 业务逻辑区域
const togglePasswordVisibility = () => {
  showPassword.value = !showPassword.value;
};

const validateEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

const handleCreateAdmin = async () => {
  if (!isFormValid.value || submitting.value) {
    return;
  }

  // 简单表单验证
  if (createForm.nickname.length < 2 || createForm.nickname.length > 50) {
    showUIFeedback.warning(t('nicknameLength'));
    return;
  }

  if (!validateEmail(createForm.email)) {
    showUIFeedback.warning(t('emailInvalid'));
    return;
  }

  if (createForm.password.length < 6 || createForm.password.length > 20) {
    showUIFeedback.warning(t('passwordLength'));
    return;
  }

  try {
    submitting.value = true;
    
    // 调用创建管理员API
    const response = await ApiAdmin.createAdmin({
      nickname: createForm.nickname,
      email: createForm.email,
      password: createForm.password,
      is_admin: createForm.is_admin
    });

    if (response.code === 200) {
      
      // 显示账户信息并复制到剪贴板
      const adminInfo = {
        nickname: createForm.nickname,
        email: createForm.email,
        password: createForm.password
      };
      const data= { ...adminInfo,...response.data }

      // 通知父组件管理员创建成功
      emit('onAdminCreated', data);
      
      // 重置表单
      resetForm();
      
      // 关闭弹窗
      handleClose();
    } else {
      throw new Error(response.message || 'Create admin failed');
    }
  } catch (error) {
    console.error('Create admin error:', error);
    showUIFeedback.error(error.message || t('createError'));
  } finally {
    submitting.value = false;
  }
};

// 数据解析区域
const resetForm = () => {
  createForm.nickname = '';
  createForm.email = '';
  createForm.password = '';
  createForm.is_admin = false;
};

// 初始化方法区域
const initData = () => {
  resetForm();
};

// 周期函数区域
onMounted(() => {
  initData();
});

// 导出区域
defineExpose({
  resetForm
});
</script>

